INSERT INTO quotation (
    quotation_id, shipper_id, origin_unlocode, destination_unlocode,
    arrival_deadline, cargo_type, weight_kg, estimated_amount,
    estimated_currency, valid_until, status
) VALUES (
    #{quotationId}, #{shipperId}, #{originUnlocode}, #{destinationUnlocode},
    #{arrivalDeadline}, #{cargoType}, #{weightKg}, #{estimatedAmount},
    #{estimatedCurrency}, #{validUntil}, #{status}
)

INSERT INTO quotation_candidate (
    quotation_id, candidate_seq, estimated_days, estimated_cost,
    estimated_currency, itinerary_summary
) VALUES (
    #{quotationId}, #{candidateSeq}, #{estimatedDays}, #{estimatedCost},
    #{estimatedCurrency}, #{itinerarySummary}
)
